export interface ObservabilityPipelineConfigDestinationSplunkHec {
    /**
     * If `true`, Splunk tries to extract timestamps from incoming log events. If `false`, Splunk assigns the time the event was received. Only applies when `endpointTarget` is `event`; cannot be `true` when `endpointTarget` is `raw`.
     */
    autoExtractTimestamp?: boolean;
    /**
     * Configuration for buffer settings on destination components. Exactly one of `disk` or `memory` must be specified.
     */
    buffer?: outputs.ObservabilityPipelineConfigDestinationSplunkHecBuffer;
    /**
     * Encoding format for log events. Valid values are `json`, `rawMessage`.
     */
    encoding: string;
    /**
     * The Splunk HEC endpoint to send events to. Use `event` to send structured events to the `/event` endpoint, or `raw` to send the raw message to the `/raw` endpoint. Valid values are `event`, `raw`.
     */
    endpointTarget?: string;
    /**
     * Name of the environment variable or secret that holds the Splunk HEC endpoint URL.
     */
    endpointUrlKey?: string;
    /**
     * Optional name of the Splunk index where logs are written.
     */
    index?: string;
    /**
     * List of log field names to send as indexed fields to Splunk HEC. Available only when `encoding` is `json`.
     */
    indexedFields?: string[];
    /**
     * The Splunk sourcetype to assign to log events.
     */
    sourcetype?: string;
    /**
     * Name of the environment variable or secret that holds the Splunk HEC token.
     */
    tokenKey?: string;
    /**
     * Controls how the Splunk HEC token is supplied. Use `custom` to provide a token via `tokenKey`, or `fromSource` to forward the token received from an upstream Splunk HEC source. Valid values are `custom`, `fromSource`.
     */
    tokenStrategy?: string;
}

